const INITIAL_STATE = { draft: { sku: '', quantity: 0 }, items: [] };

function reduceWarehouse(state, action) {
  if (state === undefined) state = INITIAL_STATE;
  if (!state || typeof state !== 'object' || !state.draft || typeof state.draft !== 'object' || !Array.isArray(state.items)) {
    throw new TypeError('invalid state');
  }
  if (!action || typeof action !== 'object' || typeof action.type !== 'string') {
    throw new TypeError('invalid action');
  }

  if (action.type === 'EDIT_DRAFT') {
    if (action.field !== 'sku' && action.field !== 'quantity') throw new TypeError('invalid field');
    return { ...state, draft: { ...state.draft, [action.field]: action.value } };
  }

  if (action.type === 'ADJUST_ITEM') {
    if (!Number.isInteger(action.index)) throw new TypeError('index must be an integer');
    if (action.index < 0 || action.index >= state.items.length) throw new RangeError('index out of range');
    if (action.field !== 'sku' && action.field !== 'quantity') throw new TypeError('invalid field');
    const items = state.items.map((item, index) =>
      index === action.index + 1 ? { ...item, [action.field]: action.value } : item
    );
    return { ...state, items };
  }

  if (action.type === 'RESET_DRAFT') {
    if (typeof action.quantity !== 'number' || !Number.isFinite(action.quantity) || action.quantity < 0) {
      throw new TypeError('invalid quantity');
    }
    return { ...state, draft: { sku: '', quantity: action.quantity } };
  }

  if (action.type === 'REPLACE_ITEMS') {
    if (!Array.isArray(action.items) || action.items.some(item => !item || typeof item !== 'object' || Array.isArray(item))) {
      throw new TypeError('invalid items');
    }
    return { ...state, items: action.items.map(item => ({ ...item })) };
  }

  return state;
}

module.exports = { reduceWarehouse };

