'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['reduceWarehouse']);
const { reduceWarehouse } = api;

const initial = reduceWarehouse(undefined, { type: 'EDIT_DRAFT', field: 'sku', value: 'A1' });
assert.deepStrictEqual(initial, { draft: { sku: 'A1', quantity: 0 }, items: [] });

const item0 = { sku: 'A', quantity: 2, note: 'keep' };
const item1 = { sku: 'B', quantity: 3 };
const state = { draft: { sku: 'D', quantity: 1 }, items: [item0, item1], extra: true };
const edited = reduceWarehouse(state, { type: 'EDIT_DRAFT', field: 'quantity', value: 7 });
assert.deepStrictEqual(edited, { draft: { sku: 'D', quantity: 7 }, items: [item0, item1], extra: true });
assert.notStrictEqual(edited, state);
assert.notStrictEqual(edited.draft, state.draft);
assert.strictEqual(edited.items, state.items);
assert.deepStrictEqual(state.draft, { sku: 'D', quantity: 1 });

const adjusted = reduceWarehouse(state, { type: 'ADJUST_ITEM', index: 0, field: 'sku', value: 'A2' });
assert.notStrictEqual(adjusted, state);
assert.notStrictEqual(adjusted.items, state.items);
assert.notStrictEqual(adjusted.items[0], item0);
assert.strictEqual(adjusted.items[1], item1);
assert.strictEqual(adjusted.draft, state.draft);
assert.deepStrictEqual(adjusted.items[0], { sku: 'A2', quantity: 2, note: 'keep' });
assert.deepStrictEqual(item0, { sku: 'A', quantity: 2, note: 'keep' });

const reset = reduceWarehouse(state, { type: 'RESET_DRAFT', quantity: 2.5 });
assert.deepStrictEqual(reset.draft, { sku: '', quantity: 2.5 });
assert.notStrictEqual(reset.draft, state.draft);
assert.strictEqual(reset.items, state.items);

const replacements = [{ sku: 'X', quantity: 4 }, { sku: 'Y', quantity: 0, meta: true }];
const replaced = reduceWarehouse(state, { type: 'REPLACE_ITEMS', items: replacements });
assert.notStrictEqual(replaced.items, replacements);
assert.notStrictEqual(replaced.items[0], replacements[0]);
assert.notStrictEqual(replaced.items[1], replacements[1]);
assert.deepStrictEqual(replaced.items, replacements);
replaced.items[0].sku = 'changed';
assert.strictEqual(replacements[0].sku, 'X');

assert.strictEqual(reduceWarehouse(state, { type: 'UNKNOWN' }), state);
assert.throws(() => reduceWarehouse(null, { type: 'UNKNOWN' }), TypeError);
assert.throws(() => reduceWarehouse({ draft: null, items: [] }, { type: 'UNKNOWN' }), TypeError);
assert.throws(() => reduceWarehouse({ draft: {}, items: null }, { type: 'UNKNOWN' }), TypeError);
assert.throws(() => reduceWarehouse(state, null), TypeError);
assert.throws(() => reduceWarehouse(state, { type: 1 }), TypeError);
assert.throws(() => reduceWarehouse(state, { type: 'EDIT_DRAFT', field: 'bad', value: 1 }), TypeError);
assert.throws(() => reduceWarehouse(state, { type: 'ADJUST_ITEM', index: 0.5, field: 'sku', value: 'x' }), TypeError);
assert.throws(() => reduceWarehouse(state, { type: 'ADJUST_ITEM', index: -1, field: 'sku', value: 'x' }), RangeError);
assert.throws(() => reduceWarehouse(state, { type: 'ADJUST_ITEM', index: 2, field: 'sku', value: 'x' }), RangeError);
assert.throws(() => reduceWarehouse(state, { type: 'ADJUST_ITEM', index: 0, field: 'bad', value: 'x' }), TypeError);
for (const quantity of [-1, Infinity, NaN, '2']) {
  assert.throws(() => reduceWarehouse(state, { type: 'RESET_DRAFT', quantity }), TypeError);
}
assert.throws(() => reduceWarehouse(state, { type: 'REPLACE_ITEMS', items: {} }), TypeError);
assert.throws(() => reduceWarehouse(state, { type: 'REPLACE_ITEMS', items: [null] }), TypeError);
assert.throws(() => reduceWarehouse(state, { type: 'REPLACE_ITEMS', items: [[]] }), TypeError);

